SELECT id, product_id, order_id, quantity, unit_price, ROW_NUMBER() OVER (PARTITION BY product_id, order_id ORDER BY quantity DESC, id) AS row_num, LAG(unit_price, 1, 0) OVER (PARTITION BY product_id ORDER BY quantity, id) AS prev_unit_price FROM order_items WHERE order_id IN (16, 29) ORDER BY id DESC;
